def simplify(x, n):
    def fraction_to_decimal(frac):
        numerator, denominator = map(int, frac.split('/'))
        return numerator / denominator

    x_decimal = fraction_to_decimal(x)
    n_decimal = fraction_to_decimal(n)

    result = x_decimal * n_decimal
    return result.is_integer()
